/**
 * Minimal Cloudflare binding types for the Next.js app code.
 * (Full Workers types live in cloudflare-env.d.ts, generated by `npm run cf-typegen`,
 * and are used by the worker/ entry; they are kept out of the app's DOM type-check.)
 */
declare global {
  interface CloudflareEnv {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    DB: any;
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    AI: any;
    AI_TEXT_MODEL?: string;
    AI_VISION_MODEL?: string;
    AUTH_SECRET?: string;
    INTERNAL_SECRET?: string;
    DEMO_RESET_KEY?: string;
  }
}
export {};
